<?php
namespace App\Http\Controllers;
use App\Models\{SeoCampaign, SeoCompetitor, SeoKeyword};
use Illuminate\Http\Request;
use Illuminate\Validation\Rule;

class SeoKeywordController extends Controller
{
 public function index(SeoCampaign $campaign, Request $request){$this->authorize('view',$campaign);$keywords=$campaign->keywords()->with(['rankings'=>fn($q)=>$q->latest('checked_on')])->latest()->get();return view('seo.keywords.index',compact('campaign','keywords'));}
 public function store(Request $request, SeoCampaign $campaign){$this->authorize('contribute',$campaign);$d=$request->validate(['keyword'=>'required|string|max:255','target_page_url'=>'nullable|url|max:2048','category'=>'nullable|string|max:100','location'=>'nullable|string|max:150','device'=>['required',Rule::in(['desktop','mobile'])],'search_volume'=>'nullable|integer|min:0','keyword_difficulty'=>'nullable|numeric|min:0|max:100','priority'=>['required',Rule::in(['high','medium','low'])],'initial_rank_position'=>'nullable|integer|min:1|max:10000','initial_checked_on'=>'nullable|date']);$initialRank=$d['initial_rank_position'] ?? null;$initialCheckedOn=$d['initial_checked_on'] ?? now()->toDateString();unset($d['initial_rank_position'],$d['initial_checked_on']);$d += ['normalized_keyword'=>mb_strtolower(trim(preg_replace('/\s+/', ' ', $d['keyword']))),'language'=>'en','search_engine'=>'google','created_by'=>auth()->id()];$keyword=$campaign->keywords()->create($d);if(!is_null($initialRank)){$keyword->rankings()->create(['checked_on'=>$initialCheckedOn,'rank_position'=>$initialRank,'source'=>'manual','recorded_by'=>auth()->id()]);}return back()->with('success',$initialRank ? 'Keyword and initial ranking saved.' : 'Keyword added. Use Update to add its first ranking snapshot.');}
 public function destroy(SeoCampaign $campaign, SeoKeyword $keyword){$this->authorize('contribute',$campaign);abort_unless($keyword->seo_campaign_id===$campaign->id,404);$keyword->delete();return back()->with('success','Keyword deleted.');}
 public function addRanking(Request $request, SeoCampaign $campaign, SeoKeyword $keyword){$this->authorize('contribute',$campaign);abort_unless($keyword->seo_campaign_id===$campaign->id,404);$d=$request->validate(['checked_on'=>'required|date','rank_position'=>'nullable|integer|min:1|max:10000','source'=>'required|string|max:100','remarks'=>'nullable|string|max:2000']);$keyword->rankings()->updateOrCreate(['checked_on'=>$d['checked_on'],'source'=>$d['source']],$d+['recorded_by'=>auth()->id()]);return back()->with('success','Ranking snapshot saved.');}
 public function competitors(SeoCampaign $campaign){$this->authorize('view',$campaign);return view('seo.competitors.index',['campaign'=>$campaign,'competitors'=>$campaign->competitors()->latest()->get()]);}
 public function storeCompetitor(Request $request, SeoCampaign $campaign){$this->authorize('contribute',$campaign);$d=$request->validate(['name'=>'required|string|max:255','website_url'=>'required|url|max:512','services'=>'nullable|string|max:3000','strengths'=>'nullable|string|max:3000','weaknesses'=>'nullable|string|max:3000','opportunities'=>'nullable|string|max:3000','notes'=>'nullable|string|max:3000','data_source'=>'nullable|string|max:100']);$campaign->competitors()->create($d+['created_by'=>auth()->id()]);return back()->with('success','Competitor added. Third-party estimates must include their data source.');}
}
